import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
s = sum(a)
if s % 2:
    print("NO")
else:
    t = s // 2
    dp = [False] * (t + 1)
    dp[0] = True
    for x in a:
        for j in range(t, x - 1, -1):
            if dp[j - x]:
                dp[j] = True
    print("YES" if dp[t] else "NO")

